import {empty,validate} from '../../src/finance/model.ts';
import {emptyLedgerDraft} from '../../src/finance/entry-system/contracts.ts';
import {postOperation,recordSettlement,recordInvoicePayment,recordTransfer} from '../../src/finance/entry-system/commands.ts';
export function syntheticLedgerState(){const s=empty();s.settings.salary=100000;s.settings.cushion=1000;let l=emptyLedgerDraft();l.accounts=[{id:'cash-a',type:'bank',name:'Conta sintética A',archived:false},{id:'cash-b',type:'cash',name:'Conta sintética B',archived:false},{id:'card-account',type:'credit_card',name:'Cartão sintético',archived:false}];l.cards=[{id:'card-a',accountId:'card-account',name:'Cartão sintético'}];for(const [id,type,amountCents,extra] of [['e','expense',10000,{}],['i','income',5000,{}],['w','income',100000,{salary:true}],['r','reimbursement',2000,{}],['c','card',6000,{cardId:'card-a',confirmed:true}]])l=postOperation(l,{id,type,amountCents,...extra,description:'Operação sintética '+id,operationDate:'2026-11-13',period:'2026-11',cancelled:false});l.invoices=[{id:'invoice-a',cardId:'card-a',period:'2026-11',installmentIds:['c']}];for(const [operationId,amountCents] of [['e',3000],['i',2000],['w',40000],['r',500]])l=recordSettlement(l,{id:'s-'+operationId,operationId,amountCents,date:'2026-11-13',accountId:'cash-a',method:'Pix',note:'Sintético'});l=recordInvoicePayment(l,{id:'ip',invoiceId:'invoice-a',amountCents:2000,date:'2026-11-13',accountId:'cash-a',method:'Pix',note:''});l=recordTransfer(l,{id:'t',fromAccountId:'cash-a',toAccountId:'cash-b',amountCents:1000,date:'2026-11-13',note:'Sintético',confirmed:true});s.entryLedger=l;validate(s);return s;}
